.slow .status::before { background: #c76558; }
.empty { text-align: center; padding: 35px 16px; color: var(--muted); }
.empty strong { display: block; margin-bottom: 5px; color: var(--ink); }
.footnote { padding: 12px 19px; border-top: 1px solid var(--line); font-size: 11px; color: var(--muted); line-height: 1.5; }
@media (max-width: 750px) {
  .masthead-inner, main { width: calc(100% - 32px); }
  main { padding-top: 28px; }
  .filters { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 460px) {
  .summary { gap: 7px; }
  .metric { padding: 12px 9px; }
  .metric-head { font-size: 11px; min-height: 26px; }
  .metric-icon { display: none; }
  .metric strong { font-size: 24px; }
  .metric small { font-size: 11px; }
  .panel-head { align-items: flex-start; flex-direction: column; }
}
</style>
</head>
<body>
<header class="masthead">
  <div class="masthead-inner">
    <div class="brand"><span class="brand-mark" aria-hidden="true"><ryugi-icon name="activity" size="19"></ryugi-icon></span> API observability</div>
    <span class="sample">Sample data</span>
  </div>
</header>
<main>
  <section class="intro" aria-labelledby="page-title">
    <h1 id="page-title">Latency explorer</h1>
    <p>Compare typical (p50) and tail (p95) response times across 24 API endpoints.</p>
  </section>

  <section class="summary" aria-label="Summary for matching endpoints">
    <div class="metric">
      <div class="metric-head">Matching endpoints <span class="metric-icon" aria-hidden="true"><ryugi-icon name="layers" size="16"></ryugi-icon></span></div>
      <strong id="matching-stat">24</strong>
      <small>of 24 endpoints</small>
    </div>
    <div class="metric">
      <div class="metric-head">Median endpoint p95 <span class="metric-icon" aria-hidden="true"><ryugi-icon name="timer" size="16"></ryugi-icon></span></div>
      <strong id="median-stat">—</strong>
      <small>Among matching endpoints</small>
    </div>
    <div class="metric">
      <div class="metric-head">Slow endpoints <span class="metric-icon" aria-hidden="true"><ryugi-icon name="triangle-alert" size="16"></ryugi-icon></span></div>
      <strong id="slow-stat">—</strong>
      <small id="slow-description">p95 above 500 ms</small>
    </div>
  </section>

  <section class="panel" aria-labelledby="endpoints-heading">
    <div class="panel-head">
      <div class="heading"><h2 id="endpoints-heading">Endpoints</h2><output class="count" id="result-count" aria-live="polite"></output></div>
      <div class="legend" aria-label="Latency profile legend">
        <span><i class="swatch"></i> p50</span>
        <span><i class="swatch p95"></i> p95</span>
        <span><i class="swatch limit"></i> Slow threshold</span>
      </div>
    </div>

    <div class="filters">
      <div class="field">
        <label for="path-search">Search path</label>
        <div class="control search">
          <ryugi-icon name="search" size="15" aria-hidden="true"></ryugi-icon>
          <input id="path-search" type="search" placeholder="e.g. /orders" autocomplete="off">
        </div>
      </div>
      <div class="field">
        <label for="method-filter">HTTP method</label>
        <div class="control">
          <select id="method-filter">
            <option value="">All methods</option>
            <option>GET</option><option>POST</option><option>PATCH</option><option>DELETE</option>
          </select>
        </div>
      </div>
      <div class="field">
        <label for="p95-sort">Sort by p95</label>
        <div class="control">
          <select id="p95-sort">
            <option value="desc">Highest first</option>
            <option value="asc">Lowest first</option>
          </select>
        </div>
      </div>
      <div class="field">
        <label for="slow-threshold">Slow threshold</label>
        <div class="control threshold">
          <input id="slow-threshold" type="number" value="500" min="0" step="any" aria-describedby="threshold-help">
          <span class="unit" aria-hidden="true">ms</span>
        </div>
      </div>
    </div>

    <div class="table-wrap">
      <table aria-labelledby="endpoints-heading">
        <colgroup>
          <col style="width: 11%"><col style="width: 30%"><col style="width: 10%">
          <col style="width: 10%"><col style="width: 25%"><col style="width: 14%">
        </colgroup>
        <thead>
          <tr>
            <th scope="col">Method</th>
            <th scope="col">Path</th>
            <th scope="col" class="latency">p50 (ms)</th>
            <th scope="col" class="latency" id="p95-header" aria-sort="descending">
              <button type="button" id="p95-toggle">p95 (ms) <span id="sort-arrow" aria-hidden="true">↓</span></button>
            </th>
            <th scope="col">Latency profile</th>
            <th scope="col">Status</th>
          </tr>
        </thead>
        <tbody id="endpoint-rows"></tbody>
      </table>
    </div>
    <p class="footnote" id="threshold-help">An endpoint is slow when its p95 exceeds the threshold in milliseconds.</p>
  </section>
</main>

<script>
const endpoints = [
  ['"'POST', '/v1/reports/export', 365, 1240],
  ['GET', '/v1/analytics/overview', 214, 920],
  ['POST', '/v1/orders', 192, 780],
  ['GET', '/v1/search', 136, 665],
  ['POST', '/v1/files', 174, 612],
  ['GET', '/v1/orders/:id/events', 129, 548],
  ['POST', '/v1/payments', 148, 472],
  ['GET', '/v1/invoices', 113, 416],
  ['GET', '/v1/orders', 96, 382],
  ['GET', '/v1/products', 83, 350],
  ['POST', '/v1/auth/login', 99, 317],
  ['PATCH', '/v1/orders/:id', 79, 284],
  ['GET', '/v1/customers', 71, 255],
  ['POST', '/v1/customers', 84, 224],
  ['GET', '/v1/orders/:id', 62, 203],
  ['GET', '/v1/products/:id', 49, 176],
  ['PATCH', '/v1/customers/:id', 57, 163],
  ['GET', '/v1/customers/:id', 43, 140],
  ['DELETE', '/v1/files/:id', 46, 125],
  ['POST', '/v1/auth/refresh', 40, 112],
  ['PATCH', '/v1/users/me', 38, 101],
  ['GET', '/v1/users/me', 27, 78],
  ['DELETE', '/v1/sessions/:id', 23, 62],
  ['GET', '/v1/health', 9, 24],
];

const byId = (id) => document.getElementById(id);
const search = byId('path-search');
const method = byId('method-filter');
const sort = byId('p95-sort');
const threshold = byId('slow-threshold');
const format = new Intl.NumberFormat('en', { maximumFractionDigits: 2 });
const maxP95 = Math.max(...endpoints.map((endpoint) => endpoint[3]));
const defaultThreshold = Number(threshold.defaultValue);

function render() {
  const query = search.value.trim().toLowerCase();
  const enteredThreshold = threshold.valueAsNumber;
  const limit = Math.max(0, Number.isFinite(enteredThreshold) ? enteredThreshold : defaultThreshold);
  const descending = sort.value === 'desc';
  const visible = endpoints
    .filter(([verb, path]) => ("'!method.value || verb === method.value) && path.toLowerCase().includes(query))
    .sort((left, right) => descending ? right[3] - left[3] : left[3] - right[3]);
  const total = visible.length;
  const median = total ? (visible[Math.floor((total - 1) / 2)][3] + visible[Math.floor(total / 2)][3]) / 2 : null;
  const slowCount = visible.filter((endpoint) => endpoint[3] > limit).length;
  const scale = Math.max(maxP95, limit);
  const percent = (value) => 100 * (value / scale);

  byId('"'matching-stat').textContent = total;
  byId('median-stat').textContent = median === null ? '—' : format.format(median) + ' ms';
  byId('slow-stat').textContent = slowCount;
  byId('slow-description').textContent = 'p95 above ' + limit.toLocaleString('en', { maximumSignificantDigits: 17 }) + ' ms';
  byId('result-count').textContent = total + (total === 1 ? ' result' : ' results');
  byId('p95-header').setAttribute('aria-sort', descending ? 'descending' : 'ascending');
  byId('sort-arrow').textContent = descending ? '↓' : '↑';

  // Row markup interpolates only fixed sample data and calculated numbers.
  byId('endpoint-rows').innerHTML = total ? visible.map(([verb, path, p50, p95]) => {
    const slow = p95 > limit;
    return "'`
      <tr class="${slow ? '"'slow' : ''}\">
        <td><span class=\"method "'${verb.toLowerCase()}">${verb}</span></td>
        <td class="path">${path}</td>
        <td class="latency">${format.format(p50)}</td>
        <td class="latency p95-num">${format.format(p95)}</td>
        <td><div class="track" aria-hidden="true">
          <span class="bar p95" style="width:${percent(p95)}%"></span>
          <span class="bar p50" style="width:${percent(p50)}%"></span>
          <span class="cutoff" style="left:${percent(limit)}%"></span>
        </div></td>
        <td><span class="status">${slow ? '"'Slow' : 'Within limit'}</span></td>
      </tr>"'`;
  }).join('"'') : '<tr><td class=\"empty\" colspan=\"6\"><strong>No matching endpoints</strong>Try a different path or HTTP method.</td></tr>';
}

for (const control of [search, method, sort, threshold]) {
  control.addEventListener('input', render);
  control.addEventListener('change', render);
}
byId('p95-toggle').addEventListener('click', () => {
  sort.value = sort.value === 'desc' ? 'asc' : 'desc';
  sort.dispatchEvent(new Event('change', { bubbles: true }));
});
render();
</script>
</body>
</html>
EOF"
